"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[16711],{2057:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>n,toc:()=>h});const n=JSON.parse('{"id":"tangfen/labortheoryofvalue","title":"","description":"Recently, Chuanliu, Yunguzi, and others have been criticizing Marx\'s labor theory of value. I\'ve been debating with them, because in my view Marx is correct, and I naturally have the right and obligation to defend Marx. This is purely for the sake of truth, just like my defense of Miss Chan\'s correct assertion that \\"all human thoughts cannot possibly be stored in computers\\"!","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/labortheoryofvalue.md","sourceDirName":"tangfen","slug":"/tangfen/labortheoryofvalue","permalink":"/tangfen/labortheoryofvalue","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"labortheoryofvalue","title":"","hide_table_of_contents":true},"sidebar":"tangfenSidebar","previous":{"title":"[\u62ac\u6760\u95e8\u56db\u95e8\u4e3b]\uff0c\u544a\u8bc9\u4f60\u4ec0\u4e48\u662f\u5bf9\u89d2\u7ebf\u6cd5\uff01","permalink":"/tangfen/totgmsmz"},"next":{"title":"\u5ddd\u6d41\uff0c\u544a\u8bc9\u4f60\u4ec0\u4e48\u624d\u662f\u7c7b\u201c\u5ddd\u6d41\u610f\u5fd7\u201d\u7684\u4e1c\u897f\uff01\u4f46\u52b3\u52a8\u4e0d\u662f\uff01","permalink":"/tangfen/chliuwill"}}');var o=a(74848),i=a(28453);const s={id:"labortheoryofvalue",title:"",hide_table_of_contents:!0},r="Mathematics, the Labor Theory of Value Can Certainly Be Criticized!",l={},h=[];function u(e){const t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"mathematics-the-labor-theory-of-value-can-certainly-be-criticized",children:"Mathematics, the Labor Theory of Value Can Certainly Be Criticized!"})}),"\n",(0,o.jsx)(t.p,{children:"Recently, Chuanliu, Yunguzi, and others have been criticizing Marx's labor theory of value. I've been debating with them, because in my view Marx is correct, and I naturally have the right and obligation to defend Marx. This is purely for the sake of truth, just like my defense of Miss Chan's correct assertion that \"all human thoughts cannot possibly be stored in computers\"!"}),"\n",(0,o.jsx)(t.p,{children:'But today, Mathematics suddenly came out and said "Forum user Yunguzi\'s main purpose online is to attack Marxism as fallacious, which is actually unconstitutional speech." He also said "Regarding the labor theory of value, there\'s actually nothing to criticize about the definition." This kind of talk only invites the contempt of those genuinely discussing issues.'}),"\n",(0,o.jsx)(t.p,{children:"If there's a problem, lay it out. In the academic sphere, the concept of \"attack\" doesn't apply. Is Yunguzi, based on his own research, criticizing the labor theory of value now illegal? This can only be classified as academic discussion -- there's no question of illegality! Unless he engages in extreme behavior. The constitution guarantees freedom of speech. If one doesn't even have the freedom to criticize the labor theory of value, Marx would laugh at this, because Marx wrote the best article on freedom of speech in history!"}),"\n",(0,o.jsx)(t.p,{children:"Yunguzi, Chuanliu, and Mathematics can all have their own views, but none of them should appoint themselves as judges to define others' behavior. So statements like \"Forum user Yunguzi's main purpose online is to attack Marxism as fallacious\" -- such language should not appear in normal academic discussion. This sounds more like something a judge would say, and who appointed Mathematics as judge?"}),"\n",(0,o.jsx)(t.p,{children:"The biggest error of Chuanliu, Yunguzi, and others is treating their misunderstandings of Marx as Marx's own words. If this is unintentional, it's a matter of intelligence and academic level. If it's intentional, it's a matter of academic ethics -- it has absolutely nothing to do with the law! Just as I am a steadfast supporter of Miss Chan and also a steadfast supporter of Marx's labor theory of value, I can accept any challenge regarding either of them. But I would absolutely never appoint myself as judge to pass verdict on anyone, because I don't have that qualification, and no one in the world does, unless they are an actual judge facing a suspect confirmed through proper legal procedures!"})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}},28453:(e,t,a)=>{a.d(t,{R:()=>s,x:()=>r});var n=a(96540);const o={},i=n.createContext(o);function s(e){const t=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);